import{_ as a,o as s,c as o,a2 as t}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"kiwa v1.25 released — Perf-harness sweep (33 package p95 baseline + regression detection rollout)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.25/gh-discussions-announcement.md","filePath":"announcements/v1.25/gh-discussions-announcement.md"}'),r={name:"announcements/v1.25/gh-discussions-announcement.md"};function i(n,e,c,d,l,p){return s(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="kiwa-v1-25-released-—-perf-harness-sweep-33-package-p95-baseline-regression-detection-rollout" tabindex="-1">kiwa v1.25 released — Perf-harness sweep (33 package p95 baseline + regression detection rollout) <a class="header-anchor" href="#kiwa-v1-25-released-—-perf-harness-sweep-33-package-p95-baseline-regression-detection-rollout" aria-label="Permalink to &quot;kiwa v1.25 released — Perf-harness sweep (33 package p95 baseline + regression detection rollout)&quot;">​</a></h1><p>v1.25 is out. After v1.13-1&#39;s <code>@kiwa-lab/perf-harness</code> v0.1 landed the <code>measure</code> p50 / p95 / p99 + <code>saveBaseline</code> + <code>detectRegression</code> + <code>evaluatePerfGate</code> primitives, and v1.14-post landed <code>runPerf3Layer</code> (serial + concurrent + memory 3-layer harness), v1.25 rolls the exact same primitives out to <strong>all 33 kiwa packages</strong>. Every package now ships <code>tests/perf/{package}.perf.ts</code> + <code>test:perf</code> script + <code>.perf-baseline/{package}.json</code> under one shared SSOT (3 warmup + 100 iteration + 20 % p95 delta + Welch&#39;s t-test |t| &gt; 2). <code>@kiwa-lab/perf-harness</code> v0.1.1 → v0.2.0 minor bump reflects the 33 package coverage extension.</p><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><ul><li><strong><code>@kiwa-lab/perf-harness</code> v0.2.0</strong> (33 package coverage extension + 3-layer harness 標準化). v0.1&#39;s <code>measure</code> / <code>saveBaseline</code> / <code>loadBaseline</code> / <code>detectRegression</code> / <code>evaluatePerfGate</code> primitives + v1.14-post&#39;s <code>runPerf3Layer</code> keep every prior signature. v0.2 is a <strong>coverage extension</strong>, not a surface extension — every one of the 33 kiwa packages now consumes the same primitives under one shared SSOT (<code>docs/concepts/perf-testing-ssot.md</code>).</li><li><strong>v1.25-1 core layer perf sweep</strong> (Issue #927). 9 package (<code>@kiwa-lab/core</code> / <code>dapp</code> / <code>api</code> / <code>ui</code> / <code>data</code> / <code>cli-test</code> / <code>observability</code> / <code>e2e</code> / <code>cli</code>) each grew a <code>tests/perf/{package}.perf.ts</code> suite + <code>test:perf</code> script + <code>.perf-baseline/{package}.json</code>. Every suite uses the same <code>runPerf3Layer</code> primitive (serial concurrency=1 200 iter + concurrent concurrency=10 500 iter + memory heap sampling).</li><li><strong>v1.25-2 framework adapter perf sweep</strong> (Issue #928). 11 framework adapter (<code>a11y</code> / <code>visual</code> / <code>nextjs</code> / <code>nuxt</code> / <code>sveltekit</code> / <code>remix</code> / <code>astro</code> / <code>solidstart</code> / <code>qwikcity</code> / <code>edge</code> / <code>fresh</code> / <code>hono</code> / <code>solidjs</code>) each grew the same pattern. Framework baseline path separation prevents cross-adapter noise.</li><li><strong>v1.25-3 test type perf sweep</strong> (Issue #929). 3 test type package (<code>a11y</code> / <code>visual</code> / <code>component</code>) + 3-layer perf harness.</li><li><strong>v1.25-4 SaaS layer perf sweep</strong> (Issue #930). 10 SaaS layer package (<code>auth</code> / <code>queue</code> / <code>cache</code> / <code>orm</code> / <code>payment</code> / <code>streaming</code> / <code>search</code> / <code>mcp</code> / <code>agent</code> / <code>ai-llm</code>) + provider 別 baseline + <code>KIWA_MODE=real</code> opt-in for real sandbox measurement.</li><li><strong>v1.25-5 release-gate 統合 + docs 補強</strong> (Issue #931). <code>perf.p95Ms</code> axis integration with the 11-axis release gate. 2 tutorials (45 perf-harness baseline p95 walkthrough + 46 perf baseline migration methodology) + concept doc <code>perf-testing-ssot.md</code> (4 rule SSOT: 3 warmup + 100 iteration / Welch&#39;s t-test |t| &gt; 2 / 20 % p95 delta / baseline JSON schema) + migration guide v1.24 → v1.25 (additive-only) + snippet validation <code>docs-tutorial-v1.25.test.ts</code> (15 test) re-runs every code snippet against the real <code>@kiwa-lab/perf-harness</code> API.</li><li><strong>v1.25-6 publish</strong> (Issue #932, this PR). plugin.json 1.25.0 + description v1.25 marker + 26 new perf keywords + Roadmap ✅ v1.25 row + announcement 4 file + release-smoke <code>v1-25-publish.test.ts</code> (7 axis publish artefact invariant) + docs-e2e <code>V1_25_PAGES</code> (5 page render check) + <code>@kiwa-lab/perf-harness</code> v0.2.0 minor bump + release script filter に <code>@kiwa-lab/perf-harness</code> 追加 (v1.14 payment 漏れ再発防止、 v1.23 v1-23-payment fix 教訓反映).</li></ul><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><ul><li><strong>6 sub-Issues resolved</strong> (#927-#932)</li><li><strong>6 PRs merged</strong> (v1.25-1 + v1.25-2 + v1.25-3 + v1.25-4 + v1.25-5 + this publish PR)</li><li><strong>1 npm minor bump</strong> (<code>@kiwa-lab/perf-harness</code> v0.1.1 → v0.2.0) — kiwa runtime fixture count stays 34</li><li><strong>33 package perf sweep 完了</strong> (core layer 9 + framework adapter 11 + test type 3 + SaaS layer 10)</li><li><strong>release script filter fix</strong> — <code>@kiwa-lab/perf-harness</code> を含めて v1.14 payment 漏れ再発防止</li></ul><h2 id="why-33-package-coverage-and-not-just-3-pilot-package" tabindex="-1">Why 33 package coverage (and not just 3 pilot package) <a class="header-anchor" href="#why-33-package-coverage-and-not-just-3-pilot-package" aria-label="Permalink to &quot;Why 33 package coverage (and not just 3 pilot package)&quot;">​</a></h2><p>Perf harness rollout has 3 failure modes that a 3-pilot-package rollout can&#39;t catch, no matter how strict the pilot gate is.</p><ul><li><strong>Threshold drift</strong>. One package uses <code>p50 &lt; 5 ms</code> as the gate, another uses <code>p95 &lt; 10 ms</code>, a third uses <code>mean &lt; 8 ms</code>. When a regression fires on package A but not on B, the reader cannot tell whether B is genuinely fine or whether B&#39;s gate is looser than A&#39;s. The 11-axis release gate defines <code>perf.p95Ms</code> as the single perf axis; every downstream suite converges on that same metric.</li><li><strong>Iteration count drift</strong>. A suite that runs 10 iterations gives a p95 dominated by warmup noise. A suite that runs 10 000 iterations wastes 10 seconds per package × 33 packages. The SSOT pins <strong>3 warmup + 100 iteration</strong> as the shared floor — enough samples to make Welch&#39;s t-test meaningful, few enough that the full sweep completes in under 90 seconds.</li><li><strong>Regression detection drift</strong>. Deltas of 5 % / 10 % / 30 % all get called &quot;regression&quot; in different suites. The SSOT pins the delta threshold at <strong>20 %</strong> and the significance test at Welch&#39;s t-test (<code>|t| &gt; 2</code>). Both conditions must hold for a <code>regressed</code> verdict — a delta alone can be noise, and a t-test alone can flag a statistically-significant 1 % move that no user notices.</li></ul><p>The 4 rules in <code>docs/concepts/perf-testing-ssot.md</code> are the smallest set that make kiwa perf suites comparable across packages, milestones, and forks.</p><h2 id="_15-milestone-streak" tabindex="-1">15-milestone streak <a class="header-anchor" href="#_15-milestone-streak" aria-label="Permalink to &quot;15-milestone streak&quot;">​</a></h2><p>v1.11 (release gate) → v1.12 (non-determinism) → v1.13 (time-axis) → v1.14 (horizontal expansion) → v1.15 (AI-LLM depth) → v1.16 (component depth) → v1.17 (Observability v2) → v1.18 (Blockchain depth) → v1.19 (Framework depth) → v1.20 (Streaming depth) → v1.21 (Auth depth) → v1.22 (Auth depth II) → v1.23 (Payment depth) → v1.24 (Edge / Serverless depth) → <strong>v1.25 (Perf-harness sweep)</strong>. Every milestone since v1.11 has landed 6 sub-Issues in full.</p><h2 id="v2-0-candidates" tabindex="-1">v2.0 candidates <a class="header-anchor" href="#v2-0-candidates" aria-label="Permalink to &quot;v2.0 candidates&quot;">​</a></h2><ul><li>Multi-version Vitest matrix (Vitest 1.x vs 2.x vs 3.x parity)</li><li>Desktop (Electron / Tauri) + mobile (React Native / Expo) adapters</li><li>Coverage 100% milestone</li><li>Cache / Data depth (Dragonfly / Materialize / Neon)</li><li>L2 depth (Base / Arbitrum / Optimism / Scroll block-space fidelity)</li><li>ZK depth (Noir / Circom / RISC Zero test harness)</li><li>IoT depth (MQTT / CoAP / LWM2M)</li><li>DB depth (SurrealDB / EdgeDB / Turso)</li><li>Perf-harness sweep II — real-machine baseline (macOS ARM64 + Linux x86_64 + Windows x86_64 3 hardware matrix + CI reproducibility harness)</li></ul><p>Feedback welcome on which of these should land next.</p>',15)])])}const g=a(r,[["render",i]]);export{u as __pageData,g as default};
